-- lovable-cron-fallback-reviewed: retries only while pending work exists, no permanent polling; wake on enqueue and unschedule after drain
CREATE OR REPLACE FUNCTION public.drive_sync_finish(p_owner uuid,p_generation bigint,p_remaining boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n boolean; j bigint; BEGIN SELECT generation<>p_generation INTO n FROM public.drive_sync_runtime WHERE id=1 AND lease_owner=p_owner; IF NOT FOUND THEN RETURN; END IF; UPDATE public.drive_sync_runtime SET lease_owner=NULL,lease_until=NULL WHERE id=1 AND lease_owner=p_owner; IF n THEN PERFORM public.drive_sync_wake(); ELSIF p_remaining AND EXISTS(SELECT 1 FROM public.drive_sync_settings WHERE id=1 AND enabled) AND EXISTS(SELECT 1 FROM public.drive_sync_runtime WHERE id=1 AND callback_url IS NOT NULL) THEN IF NOT EXISTS(SELECT 1 FROM cron.job WHERE jobname='drive-sync-every-15-min') THEN PERFORM cron.schedule('drive-sync-every-15-min','*/15 * * * *','SELECT public.drive_sync_wake();'); END IF; ELSE FOR j IN SELECT jobid FROM cron.job WHERE jobname='drive-sync-every-15-min' LOOP PERFORM cron.unschedule(j); END LOOP; END IF; END $$;
CREATE FUNCTION public.drive_sync_settings_changed() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j bigint; BEGIN IF NEW.root_folder_id IS DISTINCT FROM OLD.root_folder_id OR NEW.kunder_folder_id IS DISTINCT FROM OLD.kunder_folder_id THEN UPDATE public.drive_sync_runtime SET callback_url=NULL,callback_bearer=NULL WHERE id=1; END IF; IF NOT NEW.enabled OR NEW.root_folder_id IS DISTINCT FROM OLD.root_folder_id OR NEW.kunder_folder_id IS DISTINCT FROM OLD.kunder_folder_id THEN FOR j IN SELECT jobid FROM cron.job WHERE jobname='drive-sync-every-15-min' LOOP PERFORM cron.unschedule(j); END LOOP; ELSIF NEW.enabled AND NOT OLD.enabled THEN PERFORM public.drive_sync_wake(); END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.drive_sync_settings_changed() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER drive_settings_wake AFTER UPDATE OF enabled,root_folder_id,kunder_folder_id ON public.drive_sync_settings FOR EACH ROW EXECUTE FUNCTION public.drive_sync_settings_changed();